// GENERATED by scripts/build-courses.ts from src/lib/courses/content — edit those files, then run: npm run courses
import type { LessonText } from '../types';
const text: LessonText[][] = [[{"say":"Calculus is the math of change, and it all starts with limits: what a function approaches.","blocks":[{"t":"key","text":"lim (x→a) f(x) = L means f(x) gets closer and closer to L as x gets closer to a, from both sides."},{"t":"p","text":"The value f(a) doesn't matter for the limit. A function can have a hole at x = a and still have a limit there."},{"t":"p","text":"If the left-side and right-side limits differ, the limit does not exist."},{"t":"ex","problem":"f(x) = (x² − 1)/(x − 1). What is lim (x→1) f(x)?","steps":["Plugging in gives 0/0, so simplify","(x + 1)(x − 1)/(x − 1) = x + 1"],"answer":"The limit is 2"},{"t":"tip","text":"Always try direct substitution first. Only use algebra tricks when you get 0/0."},{"t":"lab","kind":"demo","title":"A function with a hole","aim":"f(x) = (x² − 1)/(x − 1) is undefined at x = 1. What does it approach there?","sets":[{"name":"x","start":0.5,"label":"x","min":0,"max":2,"step":0.01}],"outs":[{"name":"f","expr":"(x^2 - 1)/(x - 1)","label":"f(x)"}],"steps":["Move x toward 1 from the left and from the right."],"noise":0,"result":"f(1) is undefined (0/0, shown as \"—\"), but everywhere else f(x) = x + 1, so the limit as x → 1 is 2. The graph is a line with a hole.","plot":{"x":"x","y":"f"}}]},{"say":"Limits also describe what happens far out on a graph, and whether a graph has any breaks.","blocks":[{"t":"key","text":"As x → ∞, 1/x → 0. For rational functions, compare the degrees of the top and bottom to find the limit at infinity."},{"t":"p","text":"A function is continuous at x = a if you can draw it there without lifting your pencil: f(a) exists, the limit exists, and they're equal."},{"t":"ex","problem":"lim (x→∞) (4x² + 1)/(2x² − 3)","steps":["The degrees are equal, so compare leading coefficients"],"answer":"4/2 = 2"},{"t":"p","text":"Polynomials, sin x, cos x and eˣ are continuous everywhere."}]}],[{"say":"The derivative tells you how fast something is changing at an exact instant, like a speedometer reading.","blocks":[{"t":"key","text":"The derivative f′(x) is the slope of the tangent line, defined as lim (h→0) [f(x + h) − f(x)]/h."},{"t":"p","text":"It gives the instantaneous rate of change: if s(t) is position, s′(t) is velocity."},{"t":"ex","problem":"Use the definition to find the derivative of f(x) = 3x.","steps":["[3(x + h) − 3x]/h = 3h/h = 3"],"answer":"f′(x) = 3 (the slope of the line)"},{"t":"p","text":"The power rule makes it fast: d/dx xⁿ = nxⁿ⁻¹. Constants have derivative 0, and you differentiate sums term by term."}]},{"say":"More complicated functions need a few more rules. The chain rule is the most important.","blocks":[{"t":"key","text":"Product rule: (fg)′ = f′g + fg′. Quotient rule: (f/g)′ = (f′g − fg′)/g². Chain rule: d/dx f(g(x)) = f′(g(x))·g′(x)."},{"t":"p","text":"Common derivatives: d/dx sin x = cos x, d/dx cos x = −sin x, d/dx eˣ = eˣ, d/dx ln x = 1/x."},{"t":"ex","problem":"Differentiate y = (2x + 3)⁵.","steps":["Outside: 5( )⁴; inside derivative: 2"],"answer":"10(2x + 3)⁴"},{"t":"oops","text":"The derivative of a product is not the product of the derivatives. d/dx [x · x] = 2x, not 1."},{"t":"lab","kind":"demo","title":"Inflating a balloon","aim":"A balloon's radius grows 0.5 cm per second. How fast is its volume increasing?","sets":[{"name":"t","start":4,"label":"Time (s)","min":0,"max":20,"step":0.5}],"outs":[{"name":"r","expr":"0.5*t","label":"Radius (cm)"},{"name":"V","expr":"4/3*pi*r^3","label":"Volume (cm³)"},{"name":"dV","expr":"4*pi*r^2*0.5","label":"dV/dt (cm³/s)"}],"steps":["Use the chain rule: dV/dt = dV/dr · dr/dt."],"noise":0,"result":"dV/dt = 4πr² × 0.5. You must blow air in faster and faster to keep the radius growing steadily, because the surface area keeps increasing.","plot":{"x":"t","y":"dV"}}]}],[{"say":"Derivatives describe real motion and change: speed, acceleration and growing quantities.","blocks":[{"t":"key","text":"If s(t) is position, then velocity v(t) = s′(t) and acceleration a(t) = v′(t)."},{"t":"p","text":"The object moves forward when v > 0, backward when v < 0, and is momentarily stopped when v = 0."},{"t":"ex","problem":"s(t) = t² − 6t. When is the object at rest?","steps":["v(t) = 2t − 6","2t − 6 = 0"],"answer":"t = 3"},{"t":"p","text":"Related rates problems connect the rates of related quantities, like how fast a balloon's radius grows as air is pumped in. Differentiate an equation relating the quantities with respect to time."}]},{"say":"Derivatives find the highest and lowest points of a graph. That's how we optimize real problems.","blocks":[{"t":"key","text":"At a local maximum or minimum, the derivative is zero (or undefined). These are critical points."},{"t":"list","items":["If f′ changes from + to −, there's a local maximum.","If f′ changes from − to +, there's a local minimum.","f″ > 0 means concave up (like a cup); f″ < 0 means concave down."]},{"t":"ex","problem":"A farmer has 40 m of fence for a rectangular pen. What dimensions maximize area?","steps":["2x + 2y = 40, so y = 20 − x; A = x(20 − x)","A′ = 20 − 2x = 0 gives x = 10"],"answer":"10 m by 10 m (area 100 m²)"},{"t":"lab","kind":"demo","title":"Cheapest shipping box","aim":"An open-top box with a square base must hold 1,000 cm³. Choose the base size that uses the least cardboard.","sets":[{"name":"x","start":8,"label":"Base side (cm)","min":3,"max":25,"step":0.1}],"outs":[{"name":"h","expr":"1000/x^2","label":"Height (cm)"},{"name":"S","expr":"x^2 + 4000/x","label":"Cardboard used (cm²)"}],"steps":["Set S′(x) = 2x − 4000/x² = 0 and solve."],"noise":0,"result":"S′ = 0 when x³ = 2000, so x ≈ 12.6 cm and h ≈ 6.3 cm (half the base): about 476 cm². Calculus finds the best design without trying every option.","plot":{"x":"x","y":"S"}}]}],[{"say":"Integration reverses differentiation. If you know a rate of change, you can find the original quantity.","blocks":[{"t":"key","text":"An antiderivative of f is a function F with F′ = f. ∫ xⁿ dx = xⁿ⁺¹/(n + 1) + C (n ≠ −1)."},{"t":"p","text":"The + C is needed because every constant has derivative zero, so there are infinitely many antiderivatives."},{"t":"p","text":"Other basics: ∫ cos x dx = sin x + C, ∫ eˣ dx = eˣ + C, ∫ 1/x dx = ln|x| + C."},{"t":"ex","problem":"Find ∫ (6x² − 4x + 1) dx.","steps":["6x³/3 − 4x²/2 + x"],"answer":"2x³ − 2x² + x + C"},{"t":"tip","text":"Check an antiderivative by differentiating it. You should get the original function back."}]},{"say":"A definite integral adds up infinitely many tiny pieces. It gives area, distance and total change.","blocks":[{"t":"key","text":"Fundamental Theorem of Calculus: ∫ₐᵇ f(x) dx = F(b) − F(a), where F is an antiderivative of f."},{"t":"p","text":"The definite integral gives the net area between a curve and the x-axis (area below the axis counts as negative). Integrating velocity gives displacement."},{"t":"p","text":"Riemann sums approximate integrals by adding up areas of rectangles."},{"t":"ex","problem":"Find the area under y = x² from x = 0 to x = 3.","steps":["Antiderivative: x³/3","27/3 − 0"],"answer":"9 square units"},{"t":"lab","kind":"demo","title":"Energy from solar panels","aim":"A solar array's power over a 12-hour day is P(t) = 5 sin(πt/12) kW. How much energy has it made by time T?","sets":[{"name":"T","start":6,"label":"Hours after sunrise","min":0,"max":12,"step":0.25}],"outs":[{"name":"P","expr":"5*sin(pi*T/12)","label":"Power now (kW)"},{"name":"E","expr":"60/pi*(1 - cos(pi*T/12))","label":"Energy so far (kWh)"}],"steps":["Compute E = ∫₀ᵀ 5 sin(πt/12) dt. How much energy is made over the whole day?"],"noise":0,"result":"Energy is the integral of power. The full day gives 120/π ≈ 38 kWh, and half of it comes in the middle 4 hours when the Sun is highest.","plot":{"x":"T","y":"E"}}]}]];
export default text;
